// Date helpers.
//
// Timezone strategy: timestamps (opened_at, closed_at, checked_in_at) are
// generated by PostgreSQL/the server and stored as `timestamptz` (an absolute
// instant). Calendar questions - "what is today?", "which check-ins happened on
// 2026-11-25?" - are answered in the configured APP_TIMEZONE (default
// America/Jamaica), never in the browser's timezone.

/** Calendar date ('YYYY-MM-DD') of `instant` in `timeZone`. */
export function dateInTimezone(instant, timeZone) {
  // en-CA formats dates as YYYY-MM-DD.
  return new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(instant);
}

/** Offset (ms) between `timeZone` local time and UTC at `instant`. */
function timezoneOffsetMs(instant, timeZone) {
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone,
    hourCycle: 'h23',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
  }).formatToParts(instant);
  const get = (type) => Number(parts.find((p) => p.type === type).value);
  const asUtc = Date.UTC(get('year'), get('month') - 1, get('day'), get('hour'), get('minute'), get('second'));
  return asUtc - Math.floor(instant.getTime() / 1000) * 1000;
}

/** The UTC instant of local midnight at the start of `dateString` in `timeZone`. */
function startOfDayUtc(dateString, timeZone) {
  const [y, m, d] = dateString.split('-').map(Number);
  const guess = Date.UTC(y, m - 1, d);
  // Two passes handle days where the offset changes (daylight saving time).
  let result = guess - timezoneOffsetMs(new Date(guess), timeZone);
  result = guess - timezoneOffsetMs(new Date(result), timeZone);
  return new Date(result);
}

/**
 * The [start, end) UTC instants covering one local calendar day, for
 * filtering timestamptz columns by a date chosen in the UI.
 */
export function dayRangeUtc(dateString, timeZone) {
  const [y, m, d] = dateString.split('-').map(Number);
  const next = new Date(Date.UTC(y, m - 1, d + 1)).toISOString().slice(0, 10);
  return { start: startOfDayUtc(dateString, timeZone), end: startOfDayUtc(next, timeZone) };
}

/** Convert a PostgreSQL DATE (returned by Prisma as UTC midnight) to 'YYYY-MM-DD'. */
export function toDateOnly(value) {
  return value instanceof Date ? value.toISOString().slice(0, 10) : value;
}

/** Convert 'YYYY-MM-DD' into the Date Prisma expects for a DATE column. */
export function fromDateOnly(dateString) {
  return new Date(`${dateString}T00:00:00.000Z`);
}

/** Human-readable local date-time for reports, e.g. "25 Nov 2026, 09:05:12". */
export function formatDateTime(instant, timeZone) {
  return new Intl.DateTimeFormat('en-GB', {
    timeZone,
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hourCycle: 'h23',
  }).format(instant);
}

/** Check that a 'YYYY-MM-DD' string is a real calendar date. */
export function isValidDateString(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value)) return false;
  const d = fromDateOnly(value);
  return !Number.isNaN(d.getTime()) && d.toISOString().slice(0, 10) === value;
}
